(3672949, 516676, 46314, '<td valign="top">Interesting idea, and well captured, but it doesn''t hold that much interest.</td>', 'Interesting idea, and well captured, but it doesn''t hold that much interest.', '2007-05-21 06:34:07.000000', NULL, 1),
(3672951, 516973, 30861, '<td valign="top">Someone had fun painting this one, eh?</td>', 'Someone had fun painting this one, eh?', '2007-05-21 06:34:45.000000', NULL, 1),
