(3676949, 516727, 33672, '<td valign="top">Great concept and execution. Beautiful lighting.</td>', 'Great concept and execution. Beautiful lighting.', '2007-05-21 21:29:30.000000', NULL, 1),
(3676953, 514822, 33672, '<td valign="top">Nice job keeping the blue in the water.</td>', 'Nice job keeping the blue in the water.', '2007-05-21 21:29:59.000000', NULL, 1),
(3676954, 514848, 20018, '<td valign="top">nice selection choice, one of the better ungodly number of flowers :)</td>', 'nice selection choice, one of the better ungodly number of flowers :)', '2007-05-21 21:30:10.000000', NULL, 1),
(3676973, 515230, 35645, '<td valign="top">Sorry. I just don''t care for this. There''s no interaction between photo and viewer possible other than ''oooh - a bird''. Not meaning to offend, that''s just my reaction.</td>', 'Sorry. I just don''t care for this. There''s no interaction between photo and viewer possible other than ''oooh - a bird''. Not meaning to offend, that''s just my reaction.', '2007-05-21 21:32:40.000000', NULL, 1),
