(3676983, 514295, 51538, '<td valign="top">Nicely bereft of cars - in fact that really does add value to this image.  HDR processing is not too obnoxious thankfully.  Just a bit. 8.</td>', 'Nicely bereft of cars - in fact that really does add value to this image.  HDR processing is not too obnoxious thankfully.  Just a bit. 8.', '2007-05-21 21:34:03.000000', NULL, 1),
(3676992, 513867, 35645, '<td valign="top">Wonderful. Great concept, love the pose, beautiful lighting... a very well done photo.</td>', 'Wonderful. Great concept, love the pose, beautiful lighting... a very well done photo.', '2007-05-21 21:34:44.000000', NULL, 1),
(3676995, 517041, 20018, '<td valign="top">lol, makes me hungry</td>', 'lol, makes me hungry', '2007-05-21 21:35:29.000000', NULL, 1),
(3677000, 515561, 35645, '<td valign="top">I love the tension between the two sides of the building! Great shot, and wonderful choice for this challenge.</td>', 'I love the tension between the two sides of the building! Great shot, and wonderful choice for this challenge.', '2007-05-21 21:36:38.000000', NULL, 1),
(3677007, 516707, 35645, '<td valign="top">Nice isolation of subject through the use of the desat.</td>', 'Nice isolation of subject through the use of the desat.', '2007-05-21 21:37:42.000000', NULL, 1),
(3677010, 516048, 20018, '<td valign="top">wonderful capture</td>', 'wonderful capture', '2007-05-21 21:40:21.000000', NULL, 1),
