(3701189, 516936, 46314, '<td valign="top">I like the colours. Nice scene.</td>', 'I like the colours. Nice scene.', '2007-05-27 19:19:10.000000', NULL, 1),
(3701191, 515968, 46314, '<td valign="top">Clever idea. Nicely executed.</td>', 'Clever idea. Nicely executed.', '2007-05-27 19:19:54.000000', NULL, 1),
(3701197, 516402, 46314, '<td valign="top">Decent portrait. I think I''d prefer it if it was all greyscale, rather than including the red.</td>', 'Decent portrait. I think I''d prefer it if it was all greyscale, rather than including the red.', '2007-05-27 19:21:07.000000', NULL, 1),
